using System;
using System.Linq;
using UnityEngine;
namespace LWS.TruckSnowmanBuilding
{
    public sealed partial class SnowmanMatch
    {
        string pendingStoppedRestore;bool applyingAtStartBoundary;
        [Serializable]public sealed class BodyState{public Vector3 position,velocity,angular;public Quaternion rotation;}
        [Serializable]public sealed class BallState{public string id;public BodyState body;public float radius,rolled;public int pusher;public bool packed;}
        [Serializable]public sealed class PatchState{public string id;public float[] snow;}
        [Serializable]public sealed class WorkshopState{public int version=1;public string modeId="TruckSnowmanBuilding";public string sourceMatchId;public string[] profiles;public BallState[] balls;public BodyState[] trucks;public PatchState[] patches;public float clock;public int placed,decorations,score;public bool complete;public int[] installedStyles,carriedFamilies,carriedStyles;public string[] familyIds,installedStyleIds,carriedStyleIds;}
        BodyState Capture(Rigidbody b)=>new BodyState{position=b.position,rotation=b.rotation,velocity=b.linearVelocity,angular=b.angularVelocity};
        public bool WorkshopSaveReady=>!Live&&LiftRole<0&&!decorationInterrupted&&placements.All(t=>t==null)&&Rules!=null;
        public string CaptureWorkshopJson(){if(!WorkshopSaveReady)throw new InvalidOperationException("Pause/stop at a stable workshop boundary after hoist and decoration motion finish.");var data=new WorkshopState{sourceMatchId=RestoredSourceMatchId.Length>0?RestoredSourceMatchId:MatchId,profiles=setup.players.Take(setup.count).Select(p=>p.participantId).ToArray(),balls=balls.Select(b=>new BallState{id=b.stableId,body=Capture(b.body),radius=b.radius,rolled=b.Rolled,pusher=b.LastPusher,packed=b.Packed}).ToArray(),trucks=trucks.Take(setup.count).Select(t=>Capture(t.body)).ToArray(),patches=patches.Select(p=>new PatchState{id=p.name,snow=(float[])p.Remaining.Clone()}).ToArray(),clock=Clock,placed=Rules.Placed,decorations=Rules.Decorations,complete=Rules.Complete,score=Rules.Score,familyIds=decorations.Select(d=>d.id).ToArray(),installedStyleIds=Enumerable.Range(0,6).Select(f=>decorations[f].variants[installedStyle[f]].name).ToArray(),carriedStyleIds=Enumerable.Range(0,4).Select(i=>carried[i]>=0?decorations[carried[i]].variants[carriedStyle[i]].name:"").ToArray(),installedStyles=(int[])installedStyle.Clone(),carriedFamilies=(int[])carried.Clone(),carriedStyles=(int[])carriedStyle.Clone()};return JsonUtility.ToJson(data);}
        void ApplyStoppedRestoreAtStart(){string saved=pendingStoppedRestore;pendingStoppedRestore=null;if(saved==null)return;applyingAtStartBoundary=true;try{if(!TryRestoreWorkshopJson(saved,out string reason))throw new InvalidOperationException("Stopped workshop restore no longer matches this crew: "+reason);}finally{applyingAtStartBoundary=false;}}
        static bool Finite(Vector3 p)=>float.IsFinite(p.x)&&float.IsFinite(p.y)&&float.IsFinite(p.z);
        static bool ValidBody(BodyState b){if(b==null||!Finite(b.position)||!Finite(b.velocity)||!Finite(b.angular)||b.position.magnitude>350||b.velocity.magnitude>50||b.angular.magnitude>30)return false;float q=b.rotation.x*b.rotation.x+b.rotation.y*b.rotation.y+b.rotation.z*b.rotation.z+b.rotation.w*b.rotation.w;return float.IsFinite(q)&&Mathf.Abs(q-1)<.02f;}
        public bool TryRestoreWorkshopJson(string json,out string reason)
        {
            reason="";if((Live&&!applyingAtStartBoundary)||LiftRole>=0||placements.Any(t=>t!=null)){reason="Pause/stop after hoist and decoration motion finish.";return false;}WorkshopState data;try{data=JsonUtility.FromJson<WorkshopState>(json);}catch(Exception){reason="Invalid workshop JSON.";return false;}
            if(data==null||data.version!=1||data.modeId!="TruckSnowmanBuilding"||string.IsNullOrWhiteSpace(data.sourceMatchId)||data.sourceMatchId.Length>128||data.profiles==null||!data.profiles.SequenceEqual(setup.players.Take(setup.count).Select(p=>p.participantId))||data.balls==null||data.balls.Length!=3||data.trucks==null||data.trucks.Length!=setup.count||data.patches==null||data.patches.Length!=patches.Length||data.familyIds==null||!data.familyIds.SequenceEqual(decorations.Select(d=>d.id))||data.installedStyleIds==null||data.installedStyleIds.Length!=6||data.carriedStyleIds==null||data.carriedStyleIds.Length!=4||data.installedStyles==null||data.installedStyles.Length!=6||data.carriedFamilies==null||data.carriedFamilies.Length!=4||data.carriedStyles==null||data.carriedStyles.Length!=4||data.placed<0||data.placed>3||data.decorations<0||data.decorations>63||!float.IsFinite(data.clock)||data.clock<0||data.clock>86400||data.complete&&(data.placed!=3||data.decorations!=63||data.score<=0)){reason="Unknown version, crew, IDs or invalid workshop state.";return false;}
            for(int i=0;i<3;i++){var b=data.balls[i];if(b==null||b.id!=balls[i].stableId||!ValidBody(b.body)||!float.IsFinite(b.radius)||b.radius<.7499f||b.radius>balls[i].maximumRadius+.001f||!float.IsFinite(b.rolled)||b.rolled<0||b.rolled>10000||b.pusher< -1||b.pusher>=setup.count||b.packed!=(i<data.placed)){reason="Invalid snowball identity, pose, growth or packing.";return false;}if(b.packed){if(b.rolled<8||b.radius<new[]{1.8f,1.2f,.85f}[i]){reason="Packed ball lacks eligible physical growth history.";return false;}Vector3 support=i==0?buildCenter.position:data.balls[i-1].body.position;float expected=i==0?foundation.bounds.max.y+b.radius:support.y+data.balls[i-1].radius+b.radius;if(Mathf.Abs(b.body.position.y-expected)>.25f||Vector3.ProjectOnPlane(b.body.position-support,Vector3.up).magnitude>(i==0?1.22f:data.balls[i-1].radius*.28f+.02f)){reason="Saved packing does not match actual sphere geometry.";return false;}}}
            for(int i=0;i<data.trucks.Length;i++)if(!ValidBody(data.trucks[i])){reason="Invalid tractor pose.";return false;}
            for(int i=0;i<patches.Length;i++)if(data.patches[i]==null||data.patches[i].id!=patches[i].name||!patches[i].Valid(data.patches[i].snow)){reason="Unknown patch or invalid remaining snow.";return false;}
            double consumed=0,grown=0;for(int p=0;p<patches.Length;p++)consumed+=data.patches[p].snow.Length*patches[p].cellSize*patches[p].cellSize*patches[p].depth-data.patches[p].snow.Sum(v=>(double)v);for(int b=0;b<3;b++)grown+=4*System.Math.PI*(System.Math.Pow(data.balls[b].radius,3)-System.Math.Pow(.75,3))/3;if(consumed+.2<grown){reason="Saved snowball volume exceeds consumed patch snow.";return false;}
            for(int f=0;f<6;f++)if(data.installedStyles[f]<0||data.installedStyles[f]>=decorations[f].variants.Length||data.installedStyleIds[f]!=decorations[f].variants[data.installedStyles[f]].name){reason="Unknown decoration style.";return false;}
            for(int i=0;i<4;i++)if(data.carriedFamilies[i]< -1||data.carriedFamilies[i]>5||data.carriedStyles[i]<0||data.carriedFamilies[i]>=0&&data.carriedStyles[i]>=decorations[data.carriedFamilies[i]].variants.Length||data.carriedFamilies[i]>=0&&data.carriedStyleIds[i]!=decorations[data.carriedFamilies[i]].variants[data.carriedStyles[i]].name||i>=setup.count&&data.carriedFamilies[i]>=0){reason="Invalid carried decoration.";return false;}
            // All IDs and payloads passed before the first scene write. Restore is an explicit stopped/paused operation.
            hoist.StopCrane();ClearDecor();collectionRack.ResetContacts();ResetAiDelivery();ResetAiDecorating();for(int i=0;i<3;i++){var b=data.balls[i];balls[i].Restore(b.radius,b.rolled,b.pusher,b.body.position,b.body.rotation,b.body.velocity,b.body.angular);if(!b.packed)balls[i].body.WakeUp();}for(int i=0;i<data.placed;i++)balls[i].Pack(i>0?balls[i-1]:null);for(int i=0;i<patches.Length;i++)patches[i].Restore(data.patches[i].snow);
            Rules=new SnowmanRules();Rules.Restore(data.placed,data.decorations,data.complete,data.score);Clock=data.clock;Stable=0;LiftRole=-1;Gallery=data.complete;RestoredSourceMatchId=data.sourceMatchId;decorationInterrupted=false;
            for(int i=0;i<trucks.Length;i++)trucks[i].gameObject.SetActive(i<setup.count);for(int i=0;i<setup.count;i++){var b=data.trucks[i];trucks[i].tractorMotor.Configure();trucks[i].Prepare(b.position,b.rotation,!Gallery);trucks[i].body.linearVelocity=b.velocity;trucks[i].body.angularVelocity=b.angular;carried[i]=data.carriedFamilies[i];carriedStyle[i]=data.carriedStyles[i];if(carried[i]>=0){cargo[i]=Instantiate(decorations[carried[i]].variants[carriedStyle[i]],trucks[i].transform,false);cargo[i].SetActive(true);cargo[i].transform.localPosition=new Vector3(0,2.7f,0);cargo[i].transform.localScale*=.55f;}}
            for(int f=0;f<6;f++)if((data.decorations&(1<<f))!=0){installedStyle[f]=data.installedStyles[f];installed[f]=Instantiate(decorations[f].variants[installedStyle[f]]);PoseDecoration(installed[f],f);}if(!Running)pendingStoppedRestore=json;return true;
        }
    }
}
